import csv
ts_temp = "14a08406-79a0-52ca-b8a1-8563259dc820"
ts_sp   = "22de734e-0a64-57ec-a6a5-f288ee06f947"
temp = {}
sp = {}
hours_allowed = {f"{h:02d}" for h in range(8,19)}
with open(VALUES_CSV) as f:
    r = csv.DictReader(f)
    for row in r:
        if row['timeseries_id'] not in (ts_temp, ts_sp):
            continue
        ts = row['timestamp']
        d = ts[:10]
        hm = ts[11:13]
        if hm not in hours_allowed:
            continue
        v = float(row['value'])
        if row['timeseries_id'] == ts_temp:
            temp.setdefault(d, {})[int(hm)] = v
        else:
            sp.setdefault(d, {})[int(hm)] = v

def mean_dev(d):
    devs = [temp[d][h] - sp[d][h] for h in range(8,19) if h in temp[d] and h in sp[d]]
    return sum(devs)/len(devs), len(devs)

